);
GO

CREATE TABLE dbo.ModeloTelefono (
    IdModelo INT IDENTITY(1,1) PRIMARY KEY,
    NombreModelo NVARCHAR(250) NOT NULL,
    IdMarca INT NOT NULL,
    IdSistemaOperativo INT NULL,
    IdPantalla INT NULL,
    IdBateria INT NULL,
    IdEspecificacionVideo INT NULL,
    IdProcesador INT NULL,
    FechaLanzamiento DATE NULL,
    AnioModelo INT NULL,
    Dimensiones NVARCHAR(500) NULL,
    PesoGramos DECIMAL(10,2) NULL,
    TieneNFC BIT NULL,
    TipoUSB NVARCHAR(500) NULL,
    Sensores NVARCHAR(2000) NULL,
    ColoresDisponibles NVARCHAR(2000) NULL,
    CantidadColores INT NULL,
    EsPlegable BIT NULL,
    TipoHuellaDigital NVARCHAR(300) NULL,
    PrecioPercentil10 DECIMAL(18,3) NULL,
    PrecioMediana DECIMAL(18,3) NULL,
    PrecioPercentil90 DECIMAL(18,3) NULL,

    CONSTRAINT FK_Modelo_Marca FOREIGN KEY (IdMarca)
        REFERENCES dbo.Marca(IdMarca),
    CONSTRAINT FK_Modelo_SO FOREIGN KEY (IdSistemaOperativo)
        REFERENCES dbo.SistemaOperativo(IdSistemaOperativo),
    CONSTRAINT FK_Modelo_Pantalla FOREIGN KEY (IdPantalla)
        REFERENCES dbo.Pantalla(IdPantalla),
    CONSTRAINT FK_Modelo_Bateria FOREIGN KEY (IdBateria)
        REFERENCES dbo.Bateria(IdBateria),
    CONSTRAINT FK_Modelo_Video FOREIGN KEY (IdEspecificacionVideo)
        REFERENCES dbo.EspecificacionVideo(IdEspecificacionVideo),
    CONSTRAINT FK_Modelo_Procesador FOREIGN KEY (IdProcesador)
        REFERENCES dbo.Procesador(IdProcesador)
);
GO

CREATE TABLE dbo.ConfiguracionMemoria (
    IdConfiguracion INT IDENTITY(1,1) PRIMARY KEY,
    IdModelo INT NOT NULL,
    AlmacenamientoGB INT NULL,
    RAMGB INT NULL,

    CONSTRAINT FK_Configuracion_Modelo FOREIGN KEY (IdModelo)
        REFERENCES dbo.ModeloTelefono(IdModelo)
        ON DELETE CASCADE
);
GO

CREATE TABLE dbo.OfertaTienda (
    IdOferta INT IDENTITY(1,1) PRIMARY KEY,
    IdConfiguracion INT NOT NULL,
    IdTienda INT NOT NULL,
    PrecioUSD DECIMAL(18,2) NULL,
    RangoPrecio NVARCHAR(50) NULL,
    FechaActualizacion DATETIME2 NOT NULL DEFAULT SYSDATETIME(),

    CONSTRAINT FK_Oferta_Configuracion FOREIGN KEY (IdConfiguracion)
        REFERENCES dbo.ConfiguracionMemoria(IdConfiguracion)
        ON DELETE CASCADE,
    CONSTRAINT FK_Oferta_Tienda FOREIGN KEY (IdTienda)
        REFERENCES dbo.Tienda(IdTienda)
);
GO

CREATE TABLE dbo.BitacoraOferta (
    IdBitacora BIGINT IDENTITY(1,1) PRIMARY KEY,
    IdOferta INT NULL,
    Operacion NVARCHAR(20) NOT NULL,
    PrecioAnterior DECIMAL(18,2) NULL,
    PrecioNuevo DECIMAL(18,2) NULL,
    UsuarioBD NVARCHAR(150) NOT NULL,
    FechaOperacion DATETIME2 NOT NULL DEFAULT SYSDATETIME()
);
GO

CREATE INDEX IX_Modelo_Marca ON dbo.ModeloTelefono(IdMarca);
CREATE INDEX IX_Configuracion_Modelo ON dbo.ConfiguracionMemoria(IdModelo);
CREATE INDEX IX_Oferta_Precio ON dbo.OfertaTienda(PrecioUSD);
