/*==============================================================
  PROGRAMACIÓN T-SQL
==============================================================*/

CREATE OR ALTER FUNCTION dbo.FN_TelefonoEconomicoMarca
(
    @NombreMarca NVARCHAR(100)
)
RETURNS NVARCHAR(250)
AS
BEGIN
    DECLARE @Modelo NVARCHAR(250);

    SELECT TOP (1)
        @Modelo = MT.NombreModelo
    FROM dbo.Marca AS M
    INNER JOIN dbo.ModeloTelefono AS MT
        ON MT.IdMarca = M.IdMarca
    INNER JOIN dbo.ConfiguracionMemoria AS CM
        ON CM.IdModelo = MT.IdModelo
    INNER JOIN dbo.OfertaTienda AS OT
        ON OT.IdConfiguracion = CM.IdConfiguracion
    WHERE UPPER(M.NombreMarca) = UPPER(@NombreMarca)
      AND OT.PrecioUSD IS NOT NULL
    ORDER BY OT.PrecioUSD ASC;

    RETURN ISNULL(@Modelo, N'No existe');
END;
GO

CREATE OR ALTER FUNCTION dbo.FN_TieneVariantesDetalle
(
    @IdModelo INT
)
RETURNS NVARCHAR(300)
AS
BEGIN
    DECLARE @NombreModelo NVARCHAR(250);
    DECLARE @Cantidad INT;
    DECLARE @Resultado NVARCHAR(300);

    SELECT
        @NombreModelo = MT.NombreModelo,
        @Cantidad = COUNT(CM.IdConfiguracion)
    FROM dbo.ModeloTelefono AS MT
    LEFT JOIN dbo.ConfiguracionMemoria AS CM
        ON CM.IdModelo = MT.IdModelo
    WHERE MT.IdModelo = @IdModelo
    GROUP BY MT.NombreModelo;

    IF @NombreModelo IS NULL
        SET @Resultado = N'No existe ese teléfono';
    ELSE IF @Cantidad > 1
        SET @Resultado = @NombreModelo + N' tiene varias configuraciones';
    ELSE
        SET @Resultado = @NombreModelo + N' tiene una sola configuración';

    RETURN @Resultado;
END;
GO

CREATE OR ALTER PROCEDURE dbo.SP_ContarTelefonosMarca
    @NombreMarca NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        M.NombreMarca,
        COUNT(MT.IdModelo) AS CantidadModelos
    FROM dbo.Marca AS M
    LEFT JOIN dbo.ModeloTelefono AS MT
        ON MT.IdMarca = M.IdMarca
    WHERE UPPER(M.NombreMarca) = UPPER(@NombreMarca)
    GROUP BY M.NombreMarca;
END;
GO

CREATE OR ALTER TRIGGER dbo.TRG_Oferta_ClasificarPrecio
ON dbo.OfertaTienda
AFTER INSERT, UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    UPDATE OT
    SET
        RangoPrecio =
            CASE
                WHEN I.PrecioUSD IS NULL THEN NULL
                WHEN I.PrecioUSD < 250 THEN N'Precio bajo'
                WHEN I.PrecioUSD < 1000 THEN N'Precio medio'
                ELSE N'Precio alto'
            END,
        FechaActualizacion = SYSDATETIME()
    FROM dbo.OfertaTienda AS OT
    INNER JOIN inserted AS I
        ON I.IdOferta = OT.IdOferta;
END;
GO

CREATE OR ALTER TRIGGER dbo.TRG_Oferta_AuditarPrecio
ON dbo.OfertaTienda
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

        IdOferta, Operacion, PrecioAnterior,
        PrecioNuevo, UsuarioBD, FechaOperacion
    )
    SELECT
        I.IdOferta,
        N'ACTUALIZAR',
        D.PrecioUSD,
        I.PrecioUSD,
        SUSER_SNAME(),
        SYSDATETIME()
    FROM inserted AS I
    INNER JOIN deleted AS D
        ON D.IdOferta = I.IdOferta
    WHERE ISNULL(I.PrecioUSD, -1) <> ISNULL(D.PrecioUSD, -1);
END;
GO

/*==============================================================
  SENTENCIAS DML Y PRUEBAS
==============================================================*/

SELECT TOP (100)
    M.NombreMarca,
    MT.NombreModelo,
    CM.AlmacenamientoGB,
    CM.RAMGB,
    T.NombreTienda,
    OT.PrecioUSD,
    OT.RangoPrecio
FROM dbo.ModeloTelefono AS MT
INNER JOIN dbo.Marca AS M
    ON M.IdMarca = MT.IdMarca
INNER JOIN dbo.ConfiguracionMemoria AS CM
    ON CM.IdModelo = MT.IdModelo
INNER JOIN dbo.OfertaTienda AS OT
    ON OT.IdConfiguracion = CM.IdConfiguracion
INNER JOIN dbo.Tienda AS T
    ON T.IdTienda = OT.IdTienda
ORDER BY OT.PrecioUSD;
GO

SELECT dbo.FN_TelefonoEconomicoMarca(N'apple') AS TelefonoMasEconomico;
GO

SELECT dbo.FN_TieneVariantesDetalle(1) AS DetalleVariantes;
GO

